// Input: 20 decimal adjacency masks per line. Output: 1 iff seven supports pass the six-clique demands. Bitset search, repeats allowed if a support misses nothing.
use std::io::{self,BufRead};
fn clique(adj:&[Vec<u64>],mut p:Vec<u64>,k:u32)->bool{if k==0{return true}let mut size:u32=p.iter().map(|x|x.count_ones()).sum();for w in 0..p.len(){while p[w]!=0{if size<k{return false}let b=p[w].trailing_zeros();let i=w*64+b as usize;p[w]&=p[w]-1;size-=1;if clique(adj,p.iter().zip(&adj[i]).map(|(x,y)|x&y).collect(),k-1){return true}}}false}
pub fn bounds(a:&[u32],upper:&[u32],qsize:u32,degree:u32)->bool{assert!(a.len()<32);let mut sets=vec![0u32];for (i,&v) in a.iter().enumerate(){let n=sets.len();for j in 0..n{let s=sets[j];if s&v==0{sets.push(s|1<<i)}}}let q:Vec<_>=sets.iter().filter(|&&s|s.count_ones()==qsize && upper.iter().enumerate().all(|(i,v)|s>>i&1==0 || v&s==0)).collect();let mut misses=Vec::new();for &s in &sets{if a.iter().enumerate().any(|(i,x)|s&(x|1<<i)==0){continue}let mut m=vec![0u64;(q.len()+63)/64];for (i,&&v) in q.iter().enumerate(){if s&v==0{m[i/64]|=1<<(i%64)}}if m.iter().all(|x|*x==0){return true}misses.push(m)}let n=misses.len();let w=(n+63)/64;let mut adj=vec![vec![0;w];n];for j in 0..n{for i in 0..j{if misses[i].iter().zip(&misses[j]).all(|(x,y)|x&y==0){adj[i][j/64]|=1<<(j%64)}}}let mut p=vec![0;w];for i in 0..n{p[i/64]|=1<<(i%64)}clique(&adj,p,degree)}
fn main(){let args:Vec<u32>=std::env::args().skip(1).map(|s|s.parse().unwrap()).collect();let (size,d)=if args.is_empty(){(6,7)}else{(args[0],args[1])};for row in io::stdin().lock().lines(){let a:Vec<u32>=row.unwrap().split_whitespace().map(|x|x.parse().unwrap()).collect();println!("{}",bounds(&a,&a,size,d) as u8)}}
